  const card = (name, status, kind, sub, envs, link, warn) => `<button class="dp-card ${warn === "err" ? "dp-card--err" : warn === "warn" ? "dp-card--warn" : ""}" data-a="openApp" data-app="${name}"><div class="dp-row"><span class="dp-statusdot dp-statusdot--${kind}"></span><b style="font-size:14px">${name}</b><span class="dp-spacer"></span>${status}</div><div class="dp-muted" style="font-size:12px">${sub}</div><div class="dp-envstrip">${envs}</div></button>`;
  const e = (n, s, k) => `<span class="dp-env"><span class="dp-statusdot dp-statusdot--${k}" style="width:7px;height:7px"></span>${n} · ${s}</span>`;
