  const web = card("web", pill("ok", "Running"), "ok", `${ico("branch").replace("<svg", '<svg style="width:12px;height:12px;vertical-align:-2px"')} acme/storefront · web/Dockerfile · release r-17`, e("production", "running", "ok") + e("preview", "none", "") + e("development", "idle", ""), "", "");
  const site = card("site", pill("ok", "Running"), "ok", `${ico("box").replace("<svg", '<svg style="width:12px;height:12px;vertical-align:-2px"')} nginx:1.27-alpine · existing image`, e("production", "running", "ok") + e("development", "idle", ""), "", "");
  return shell("Deployments", "Harpoon / local runtime", `
  <div class="dp-row dp-row--wrap" style="margin-bottom:14px"><div><div class="dp-kicker">Local-first deployments</div><h1 class="dp-h1">Projects</h1></div><span class="dp-spacer"></span><div class="dp-seg" role="group" aria-label="Filter"><button aria-pressed="true">All</button><button aria-pressed="false">Needs attention ${att ? '<span class="dp-count">1</span>' : ""}</button></div>${btn("create", "Create project", { cls: "btn--primary", icon: "plus" })}</div>
  ${att ? banner(d.app.kind === "err" ? "err" : "warn", "alert", `storefront / api needs attention`, esc(d.app.attention.text) + (d.auto.state === "paused" ? " Automatic deployments are paused." : ""), btn("openApp", "Open api", { data: 'data-app="api"', cls: "btn--primary" })) : ""}
  <div class="dp-h2" style="margin:6px 0 10px">storefront <span class="dp-faint" style="text-transform:none;letter-spacing:0;font-weight:400">· 2 applications · git deploy key</span></div><div class="dp-grid dp-grid--3">${api}${web}</div>
  <div class="dp-h2" style="margin:22px 0 10px">docs-site <span class="dp-faint" style="text-transform:none;letter-spacing:0;font-weight:400">· 1 application · image</span></div><div class="dp-grid dp-grid--3">${site}</div>
  <p style="margin-top:22px">${evidence()}</p>`);
