  const crumbs = `<button data-a="home">Deployments</button>${ico("chevr").replace("<svg", '<svg style="width:10px;height:10px"')}<span>storefront</span>${ico("chevr").replace("<svg", '<svg style="width:10px;height:10px"')}<strong style="color:var(--text-primary)">api</strong>`;
  const tabs = [["overview", "Overview"], ["deployments", "Deployments", d.deps.length], ["logs", "Logs"], ["metrics", "Metrics"], ["variables", "Variables"], ["settings", "Settings"]];
  const hero = `<div class="dp-panel"><div class="dp-panel__body dp-hero"><div class="dp-hero__state"><div class="big ${{ ok: "", err: "err", warn: "warn" }[a.kind] ?? ""} ${a.status === "recovering" ? "info" : ""} ${a.status === "unknown" ? "idle" : ""}">${ico(a.status === "down" ? "alert" : a.status === "recovering" ? "undo" : a.status === "unknown" ? "info" : "check")}</div><div><div class="dp-row">${pill(a.kind, a.label, { live: a.status === "recovering" })}${a.status === "running" ? `<b>release ${a.release}</b> <span class="mono dp-muted">${a.sha}</span>` : ""}</div><div class="dp-muted" style="font-size:12px;margin-top:4px">${a.status === "running" ? `<a class="dp-link" href="#" data-a="noop">http://localhost:38101</a> · ${esc(S.route.env)} · container <button class="dp-link mono" data-a="nav" data-nav="containers">storefront-api-r42</button>` : esc(a.health_note)}</div></div></div>
  <div class="dp-actions live-actions">${btn("deploy", "Deploy", { cls: "btn--primary", icon: "rocket", disabled: !connected() })}${btn("redeploy", "Redeploy", { icon: "refresh", disabled: !connected() })}${btn("rollbackPick", "Roll back…", { icon: "undo", disabled: !connected() || a.status === "recovering" })}${btn("promote", "Promote…", { icon: "up", disabled: !connected() })}</div></div></div>`;
  const att = a.attention ? banner(a.attention.kind, a.attention.kind === "info" ? "info" : "alert", { info: "Deploying", warn: "Needs attention", err: "Application down" }[a.attention.kind], esc(a.attention.text), (S.scenario === "restore-failed" ? btn("recover", "Retry recovery", { cls: "btn--primary", icon: "undo", disabled: !connected() }) + btn("rollbackPick", "Roll back to d-41", { disabled: !connected() }) : "") + btn("openDep", "Inspect d-43", { data: 'data-dep="d-43"' })) : "";
  const autoBanner = d.auto.state === "paused" ? banner("warn", "pause", "Automatic deployments are paused", `${esc(d.auto.reason)} <b>${d.auto.held.length} push${d.auto.held.length === 1 ? "" : "es"} held</b> — nothing was discarded. Manual deployments still work.`, btn("resume", "Review & resume…", { cls: "btn--primary", icon: "play", disabled: !connected() })) : "";
  const envSeg = `<div class="dp-seg" role="group" aria-label="Environment">${["development", "preview", "production"].map((e) => `<button data-a="env" data-env="${e}" aria-pressed="${env === e}">${e[0].toUpperCase() + e.slice(1)}</button>`).join("")}</div>`;
  let body = "";
