  const bar = `<div class="dp-seg"><button data-a="logtab" data-t="build" aria-pressed="${bt}">Build ${live ? '<span class="dp-pill dp-pill--info dp-pill--live" style="height:16px">live</span>' : ""}</button><button data-a="logtab" data-t="runtime" aria-pressed="${!bt}">Application</button></div><input class="dp-input" id="logq" placeholder="Filter" value="${esc(S.logFilter)}" aria-label="Filter log"><label class="dp-muted"><input type="checkbox" data-a="follow" ${S.follow ? "checked" : ""}> Follow</label><span class="dp-spacer"></span><span class="dp-faint">${bt ? "d-43 · stored with the deployment record" : "live from Docker · Harpoon shows what Docker keeps"}</span>${btn("noop", "Copy", { sm: true, icon: "copy" })}`;
